-- Saved-output scope, reload, legacy reads and failed replacement rollback; fictional transaction only.
RESET ROLE;
INSERT INTO public.projects(id,user_id,name,stage) VALUES
 ('fa028000-0000-4000-8000-000000000010',firstten_policy_test.id('owner_a'),'Fictional saved-output origin fixture',3);
SET LOCAL ROLE service_role;
SELECT public.record_ai_generation(firstten_policy_test.ai_record('{"project_id":"fa028000-0000-4000-8000-000000000010","request_id":"fa028000-0000-4000-8000-000000000001"}'));
SELECT public.record_ai_generation(firstten_policy_test.ai_record('{"project_id":"fa028000-0000-4000-8000-000000000010","request_id":"fa028000-0000-4000-8000-000000000002","kind":"synthesis","prompt_id":"first-ten.synthesis","schema_id":"first-ten.synthesis.output"}'));
SELECT public.record_ai_generation(firstten_policy_test.ai_record('{"project_id":"fa028000-0000-4000-8000-000000000010","request_id":"fa028000-0000-4000-8000-000000000003","kind":"stage2","prompt_id":"first-ten.stage2","schema_id":"first-ten.stage2.output"}'));
SELECT public.record_ai_generation(firstten_policy_test.ai_record('{"project_id":"fa028000-0000-4000-8000-000000000010","request_id":"fa028000-0000-4000-8000-000000000004","kind":"stage3","prompt_id":"first-ten.stage3","schema_id":"first-ten.stage3.output"}'));
SET LOCAL ROLE authenticated;
SELECT firstten_policy_test.set_actor('owner_a');
SELECT ok((SELECT questions_origin_id IS NULL AND survey_origin_id IS NULL FROM public.projects WHERE id=firstten_policy_test.id('project_a')),'legacy questions and survey remain readable without invented origin');
SELECT lives_ok($$UPDATE public.projects SET questions='["Fictional new question"]',questions_origin_id='fa028000-0000-4000-8000-000000000001' WHERE id='fa028000-0000-4000-8000-000000000010'$$,'owner saves questions with recorded request');
SELECT is((SELECT questions_origin_id FROM public.projects WHERE id='fa028000-0000-4000-8000-000000000010'),'fa028000-0000-4000-8000-000000000001'::uuid,'readback retains questions origin');
SELECT lives_ok($$UPDATE public.projects SET questions='["Human-edited fictional question"]' WHERE id='fa028000-0000-4000-8000-000000000010'$$,'manual question edits do not erase recorded origin');
SELECT is((SELECT questions_origin_id FROM public.projects WHERE id='fa028000-0000-4000-8000-000000000010'),'fa028000-0000-4000-8000-000000000001'::uuid,'edited questions still point to source draft');
SELECT throws_ok($$UPDATE public.projects SET questions_origin_id='fa028000-0000-4000-8000-000000000002' WHERE id='fa028000-0000-4000-8000-000000000010'$$,'23514','AI origin is unavailable for this output','synthesis receipt cannot be relabeled as questions');
SELECT throws_ok($$UPDATE public.projects SET questions_origin_id='fa020000-0000-4000-8000-000000000001' WHERE id='fa028000-0000-4000-8000-000000000010'$$,'23514','AI origin is unavailable for this output','same owner different project receipt rejected');
SELECT throws_ok($$UPDATE public.projects SET questions_origin_id='fa028000-0000-4000-8000-000000000099' WHERE id='fa028000-0000-4000-8000-000000000010'$$,'23514','AI origin is unavailable for this output','fabricated receipt rejected');
SELECT lives_ok($$INSERT INTO public.learnings(id,project_id,kind,stage,data,generation_origin_id) VALUES ('fa028000-0000-4000-8000-000000000020','fa028000-0000-4000-8000-000000000010','synthesis',1,'{"problems":[]}','fa028000-0000-4000-8000-000000000002')$$,'synthesis saves its generation link');
SELECT lives_ok($$UPDATE public.learnings SET accepted=true,body='Human reviewed fictional interpretation' WHERE id='fa028000-0000-4000-8000-000000000020'$$,'human edits and acceptance preserve source');
SELECT is((SELECT generation_origin_id FROM public.learnings WHERE id='fa028000-0000-4000-8000-000000000020'),'fa028000-0000-4000-8000-000000000002'::uuid,'synthesis link survives readback and acceptance');
SELECT throws_ok($$UPDATE public.learnings SET kind='other' WHERE id='fa028000-0000-4000-8000-000000000020'$$,'23514','AI origin is unavailable for this output','saved link cannot migrate to unrelated learning kind');
SELECT lives_ok($$SELECT public.save_generated_outreach('fa028000-0000-4000-8000-000000000010',2,'fa028000-0000-4000-8000-000000000003','[{"kind":"draft","title":"Fictional invitation","body":"Unsent draft"}]','["What happened?"]')$$,'stage2 saves rows and survey atomically');
SELECT is((SELECT generation_origin_id FROM public.outreach WHERE project_id='fa028000-0000-4000-8000-000000000010' AND stage=2),'fa028000-0000-4000-8000-000000000003'::uuid,'outreach row readback retains stage2 receipt');
SELECT is((SELECT survey_origin_id FROM public.projects WHERE id='fa028000-0000-4000-8000-000000000010'),'fa028000-0000-4000-8000-000000000003'::uuid,'survey retains the same stage2 receipt');
SELECT lives_ok($$UPDATE public.outreach SET body='Human-edited unsent fictional draft' WHERE project_id='fa028000-0000-4000-8000-000000000010' AND stage=2$$,'editing outreach retains its origin');
SELECT throws_ok($$SELECT public.save_generated_outreach('fa028000-0000-4000-8000-000000000010',2,'fa028000-0000-4000-8000-000000000003','[{"kind":"draft","title":"Bad","body":""}]','[]')$$,'23514','Invalid outreach draft','invalid replacement fails before deleting old rows');
SELECT throws_ok($$SELECT public.save_generated_outreach('fa028000-0000-4000-8000-000000000010',2,'fa028000-0000-4000-8000-000000000003','[]','[1]')$$,'23514','Invalid outreach survey','invalid survey cannot partially replace plan');
SELECT is((SELECT body FROM public.outreach WHERE project_id='fa028000-0000-4000-8000-000000000010' AND stage=2),'Human-edited unsent fictional draft','old edited plan remains after both failures');
SELECT is((SELECT survey FROM public.projects WHERE id='fa028000-0000-4000-8000-000000000010'),'["What happened?"]'::jsonb,'old survey remains after failed replacement');
SELECT throws_ok($$SELECT public.save_generated_outreach('fa028000-0000-4000-8000-000000000010',2,'fa028000-0000-4000-8000-000000000004','[]','[]')$$,'23514','AI origin is unavailable for this output','stage3 receipt rejected for stage2');
SELECT throws_ok($$SELECT public.save_generated_outreach('fa028000-0000-4000-8000-000000000010',3,NULL,'[]')$$,'23514','Invalid outreach draft','new generated replacement requires receipt');
SELECT lives_ok($$SELECT public.save_generated_outreach('fa028000-0000-4000-8000-000000000010',3,'fa028000-0000-4000-8000-000000000004','[{"kind":"referral","title":"Ask","body":"Fictional referral draft"}]')$$,'stage3 saves separate scoped rows');
SELECT is((SELECT generation_origin_id FROM public.outreach WHERE project_id='fa028000-0000-4000-8000-000000000010' AND stage=3),'fa028000-0000-4000-8000-000000000004'::uuid,'stage3 retains its source request');
SELECT is((SELECT survey_origin_id FROM public.projects WHERE id='fa028000-0000-4000-8000-000000000010'),'fa028000-0000-4000-8000-000000000003'::uuid,'stage3 does not overwrite stage2 survey');
SELECT is(public.get_ai_generation_origin('fa028000-0000-4000-8000-000000000010','fa028000-0000-4000-8000-000000000001')->>'promptId','first-ten.questions','owner can inspect prompt identity after reload');
SELECT ok((public.get_ai_generation_origin('fa028000-0000-4000-8000-000000000010','fa028000-0000-4000-8000-000000000001')->'actualModel')='null'::jsonb,'missing actual model remains unknown');
SELECT ok((public.get_ai_generation_origin('fa028000-0000-4000-8000-000000000010','fa028000-0000-4000-8000-000000000001')->'costUsd')='null'::jsonb,'missing cost remains unknown');
SELECT ok(NOT public.get_ai_generation_origin('fa028000-0000-4000-8000-000000000010','fa028000-0000-4000-8000-000000000001') ?| ARRAY['user_id','provider_generation_id','prompt','output','usage'],'lookup excludes private identifiers and content');
SELECT is(public.get_ai_generation_origin('fa028000-0000-4000-8000-000000000010','fa020000-0000-4000-8000-000000000001'),NULL::jsonb,'lookup never returns another project origin');
SELECT firstten_policy_test.set_actor('owner_b');
SELECT throws_ok($$SELECT public.get_ai_generation_origin('fa028000-0000-4000-8000-000000000010','fa028000-0000-4000-8000-000000000001')$$,'42501','AI origin is unavailable','other owner cannot inspect receipt');
SELECT throws_ok($$SELECT public.save_generated_outreach('fa028000-0000-4000-8000-000000000010',2,'fa028000-0000-4000-8000-000000000003','[]','[]')$$,'42501','Project access unavailable','other owner cannot replace plan');
SELECT throws_ok($$UPDATE public.projects SET questions_origin_id='fa028000-0000-4000-8000-000000000001' WHERE id='f2000000-0000-4000-8000-000000000003'$$,'23514','AI origin is unavailable for this output','another owner cannot attach foreign request to owned project');
SELECT firstten_policy_test.set_actor('editor');
SELECT throws_ok($$SELECT public.get_ai_generation_origin('fa028000-0000-4000-8000-000000000010','fa028000-0000-4000-8000-000000000001')$$,'42501','AI origin is unavailable','editor cannot inspect private origins');
SELECT firstten_policy_test.set_actor('viewer');
SELECT throws_ok($$SELECT public.save_generated_outreach('fa028000-0000-4000-8000-000000000010',2,'fa028000-0000-4000-8000-000000000003','[]','[]')$$,'42501','Project access unavailable','viewer cannot replace private outreach');
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT public.get_ai_generation_origin('fa028000-0000-4000-8000-000000000010','fa028000-0000-4000-8000-000000000001')$$,'42501','permission denied for function get_ai_generation_origin','anonymous cannot inspect origins');
SELECT throws_ok($$SELECT public.save_generated_outreach('fa028000-0000-4000-8000-000000000010',2,'fa028000-0000-4000-8000-000000000003','[]','[]')$$,'42501','permission denied for function save_generated_outreach','anonymous cannot replace plan');
RESET ROLE;
SELECT ok((SELECT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] FROM pg_proc WHERE oid='public.get_ai_generation_origin(uuid,uuid)'::regprocedure),'lookup uses fixed definer search path');
SELECT ok((SELECT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] FROM pg_proc WHERE oid='public.save_generated_outreach(uuid,integer,uuid,jsonb,jsonb)'::regprocedure),'atomic replacement uses fixed definer search path');
DELETE FROM public.projects WHERE id='fa028000-0000-4000-8000-000000000010';
SELECT is((SELECT count(*) FROM firstten_private.ai_generation_provenance WHERE project_id='fa028000-0000-4000-8000-000000000010'),0::bigint,'deleting project cascades linked output and metadata without orphaning');
